// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer init;

    function setUp() public {
        c = new C();
        init = new Initializer();
    }

    function testFuzz_property(uint256 maintenance, uint256 fee) public {
        // keep fee-like params admissible (must be <= 1e18 = UFixed18Lib.ONE)
        maintenance = bound(maintenance, 0, 1e18);
        fee = bound(fee, 0, 1e18);

        // initialize c via raw calldata (avoids importing struct types):
        // initialize(ProductInfo calldata) where ProductInfo =
        // (string name, string symbol, PayoffDefinition, IOracleProvider oracle,
        //  UFixed18 maintenance, fundingFee, makerFee, takerFee, positionFee,
        //  makerLimit, JumpRateUtilizationCurve)
        bytes memory data = abi.encodeWithSelector(
            C.initialize.selector,
            "N",
            "S",
            (uint8(1), uint8(1), bytes30(0x01)),
            address(init), // a contract address, so the oracle validity check passes
            maintenance,
            fee,
            fee,
            fee,
            fee,
            fee,
            (int128(1), int128(2), int128(3), uint128(1))
        );
        init.init(c, data);

        // General rule: the oracle getter returns the stored contract address,
        // which is always a real (nonzero) contract address.
        assertTrue(address(c.oracle()) != address(0));
    }
}

contract Initializer {
    function init(C c, bytes memory data) external {
        (bool ok, ) = address(c).call(data);
        require(ok, "init failed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // Minimal oracle stub: any contract with code passes Address.isContract during initialize.
        OracleStub oracleStub = new OracleStub();

        // Build the ProductInfo calldata struct as raw ABI (types are not importable here):
        // (string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128))
        bytes memory initCall = abi.encodeWithSelector(
            bytes4(keccak256(
                "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"
            )),
            (
                "NAME",
                "SYM",
                (payoffType, payoffDirection, data),
                address(oracleStub),
                uint256(1e18),
                uint256(1e16),
                uint256(1e16),
                uint256(1e16),
                uint256(1e16),
                uint256(1000e18),
                (int128(1e18), int128(2e18), int128(1e18), uint128(5e17))
            )
        );

        bool initOk;
        (initOk, ) = address(c).call(initCall);

        // General rule: for ANY admissible input, if the product was successfully initialized,
        // then c.oracle() must expose a live oracle contract (nonzero address with deployed code).
        // The mutant's oracle() getter returns address(0) regardless of what was stored,
        // so it violates the rule whenever initialization succeeds (fuzzer finds such inputs).
        assertTrue(
            !initOk ||
            (address(c.oracle()) != address(0) && address(c.oracle()).code.length > 0),
            "oracle() must return the stored oracle contract after successful initialization"
        );
    }
}

contract OracleStub {
    uint256 public version;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // Keep enums in a plausible range; the fuzzer searches for a combo for which
        // initialization succeeds (the deciding input dimension).
        payoffType = uint8(bound(payoffType, 0, 4));
        payoffDirection = uint8(bound(payoffDirection, 0, 4));

        // Adversarial environment helpers: a contract acting as controller-caller and
        // an oracle address that passes the isContract check.
        Initializer init = new Initializer();
        MockOracle oracle = new MockOracle();

        bool okInit = init.init(
            c, payoffType, payoffDirection, data, address(oracle)
        );

        // General rule: whenever initialization completed successfully, the public
        // oracle() getter must expose a non-zero stored oracle address.
        assertTrue(!(okInit && address(c.oracle()) == address(0)));
    }
}

contract MockOracle {
    // minimal code-carrying target so Address.isContract(oracle) passes
}

contract Initializer {
    function init(
        C c,
        uint8 payoffType,
        uint8 payoffDirection,
        bytes30 data,
        address oracle
    ) external returns (bool) {
        bytes4 sel = bytes4(
            keccak256(
                "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"
            )
        );

        // empty strings -> fixed offsets; head is 12 words
        uint256 headLen = 12 * 32; // 0x180
        uint256 offName = headLen;
        uint256 offSymbol = offName + 64;
        uint256 offCurve = offSymbol + 64;

        bytes memory head = abi.encode(
            offName,
            offSymbol,
            payoffType,
            payoffDirection,
            data,
            uint256(uint160(oracle)),
            uint256(0), // maintenance
            uint256(0), // fundingFee
            uint256(0), // makerFee
            uint256(0), // takerFee
            uint256(0), // positionFee
            uint256(0), // makerLimit
            offCurve
        );

        bytes memory tail = abi.encode(
            uint256(0), // name length (empty string)
            uint256(0), // symbol length (empty string)
            int128(0),
            int128(0),
            int128(0),
            uint128(0)
        );

        (bool ok, ) = address(c).call(bytes.concat(bytes.concat(sel, head), tail));
        return ok;
    }
}

