pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, PayoffDefinition, PayoffType, PayoffDirection, IOracleProvider, UFixed18, Fixed18, PackedFixed18, PackedUFixed18, JumpRateUtilizationCurve, IController, ICollateral, IIncentivizer, IBeacon, IMultiInvoker, Token18, Token6, IBatcher, IEmptySetReserve, IProduct, PendingFeeUpdates} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        vm.assume(payoffDirection < 2);
        vm.assume(payoffType < 8);

        IOracleProvider oracle = IOracleProvider(address(new OracleStub()));
        IController controller = IController(address(new ControllerStub()));

        PayoffDefinition memory pd = PayoffDefinition(
            PayoffType(payoffType), PayoffDirection(payoffDirection), data
        );

        C.ProductInfo memory info = C.ProductInfo({
            name: "n",
            symbol: "s",
            payoffDefinition: pd,
            oracle: oracle,
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        });

        bool inited = true;
        try c.initialize(info) {} catch {
            inited = false;
        }

        if (inited) {
            // Rule: whenever initialization succeeds, the oracle getter must expose the
            // stored oracle contract (an address holding code), never the zero address.
            assertTrue(address(c.oracle()).code.length > 0, "oracle getter must return stored oracle with code");
        }
    }
}

contract OracleStub {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

contract ControllerStub {
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function incentivizer() external pure returns (IIncentivizer) { revert(); }
    function collateral() external pure returns (ICollateral) { revert(); }
    function paused() external pure returns (bool) { return false; }
    function owner() external pure returns (address) { return address(0); }
}
